import './Question.css'

function Question() {
    let string = ""
    for (let i = 0 ; i < 20 ; i++) {
        let random = Math.floor(Math.random() * 10);
        string += random.toString();
    }
    return (
        <div className='question'>
            string
        </div>
    )
}

export default Question;
